mapper.select:
SELECT DISTINCT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.PARENT_MENU_ID , M.SORT_ORDER , M.USE_YN , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M
INNER JOIN TB_MENU_AUTHORITY MA ON M.MENU_ID = MA.MENU_ID
AND MA.AUTHORITY_CODE IN
#{authority}
AND M.MENU_TYPE = #{menuType}
AND M.USE_YN = #{useYn}
ORDER BY M.SORT_ORDER

mapper.update:
UPDATE TB_MENU
MENU_NAME = #{menuName}, USE_YN = #{useYn}, UPDATED_BY = #{author},
WHERE MENU_ID = #{targetMenuId}
